+// FormatNamespaces validates the result of a viewable_namespaces policy decision.
+func FormatNamespaces(result any) ([]string, error) {
+	switch values := result.(type) {
+	case []string:
+		return values, nil
+	case []any:
+		namespaces := make([]string, 0, len(values))
+		for _, value := range values {
+			name, ok := value.(string)
+			if !ok {
+				return nil, fmt.Errorf("viewable_namespaces contains a non-string value: %T", value)
+			}
+			namespaces = append(namespaces, name)
+		}
+		return namespaces, nil
+	default:
+		return nil, fmt.Errorf("viewable_namespaces must be a list of strings, got %T", result)
+	}
